using System.Text.RegularExpressions;
namespace Osynix.Ats.Domain;
public static class CandidateCity {
 static readonly string[] Cities=["Abu Dhabi","Islamabad","Rawalpindi","Faisalabad","Gujranwala","Bahawalpur","Muzaffarabad","Sargodha","Sialkot","Hyderabad","Abbottabad","Peshawar","Karachi","Lahore","Multan","Quetta","Sukkur","Larkana","Mardan","Gujrat","Jhelum","Sahiwal","Wah Cantt","Mirpur","Gilgit","Skardu","Rahim Yar Khan","Dera Ghazi Khan","Dera Ismail Khan","New York","San Francisco","Los Angeles","San Diego","Washington","Chicago","Boston","Seattle","Austin","Dallas","Houston","Toronto","Vancouver","Montreal","London","Manchester","Birmingham","Edinburgh","Glasgow","Leeds","Cambridge","Oxford","Dublin","Paris","Berlin","Munich","Hamburg","Amsterdam","Rotterdam","Madrid","Barcelona","Rome","Milan","Zurich","Geneva","Stockholm","Oslo","Copenhagen","Helsinki","Warsaw","Prague","Vienna","Brussels","Lisbon","Istanbul","Ankara","Dubai","Sharjah","Ajman","Al Ain","Riyadh","Jeddah","Dammam","Khobar","Doha","Muscat","Manama","Kuwait City","Cairo","Amman","Beirut","Singapore","Hong Kong","Kuala Lumpur","Bangkok","Jakarta","Manila","Tokyo","Seoul","Beijing","Shanghai","Taipei","Sydney","Melbourne","Brisbane","Perth","Auckland","Wellington","Mumbai","New Delhi","Delhi","Bengaluru","Bangalore","Hyderabad","Chennai","Pune","Kolkata","Ahmedabad","Dhaka","Colombo","Kathmandu","Nairobi","Lagos","Cape Town","Johannesburg"];
 static readonly Regex AddressTerms=new(@"\b(house|street|road|flat|apartment|block|sector|phase|town|township|village|district|area|colony|society|avenue|lane|plot|postal|postcode|zip|dha|bahria|gulberg|clifton|cantt|cantt\.)\b",RegexOptions.IgnoreCase);
 public static string FromLegacy(string? value){if(string.IsNullOrWhiteSpace(value))return "";var found=Cities.Where(c=>Regex.IsMatch(value,@"(?<!\p{L})"+Regex.Escape(c)+@"(?!\p{L})",RegexOptions.IgnoreCase)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();found=found.Where(c=>!found.Any(other=>other!=c&&other.Contains(c,StringComparison.OrdinalIgnoreCase))).ToList();return found.Count==1?found[0]:"";}
 public static string Explicit(string? value){var text=Regex.Replace(value?.Trim()??"",@"\s+"," ");if(text.Length==0)return "";var known=FromLegacy(text);if(known.Length>0)return known;if(text.Length>80||text.Any(char.IsDigit)||AddressTerms.IsMatch(text)||text.IndexOfAny([',',';','/','\\','\n','\r'])>=0||text.Split(' ').Length>5)return "";return text;}
 public static string Display(Candidate candidate)=>candidate.City.Length>0?Explicit(candidate.City):FromLegacy(candidate.Location);
}
